describe('Update Display Name Functionality', () => {
  beforeEach(() => {
    cy.visit('/profile');
  });

  it('should successfully update display name and reflect it across the app', () => {
    // Verify initial display name
    cy.get('[data-testid="display-name"]').should('contain', 'John Doe');

    // Click edit button
    cy.get('[data-testid="edit-name-btn"]').click();

    // Verify input field appears
    cy.get('[data-testid="name-input"]').should('be.visible');

    // Update display name
    cy.get('[data-testid="name-input"]').clear().type('Jane Smith');

    // Click save button
    cy.get('[data-testid="save-name-btn"]').click();

    // Verify success message
    cy.get('[data-testid="success-toast"]').should('be.visible').should('contain', 'Name updated successfully');

    // Verify display name is updated
    cy.get('[data-testid="display-name"]').should('contain', 'Jane Smith');

    // Verify name is reflected in other parts of the app (e.g., header)
    cy.get('[data-testid="header-user-name"]').should('contain', 'Jane Smith');
  });

  it('should handle empty or invalid display name input', () => {
    // Verify initial display name
    cy.get('[data-testid="display-name"]').should('contain', 'John Doe');

    // Click edit button
    cy.get('[data-testid="edit-name-btn"]').click();

    // Attempt to save with empty name
    cy.get('[data-testid="name-input"]').clear().type('');
    cy.get('[data-testid="save-name-btn"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-toast"]').should('be.visible').should('contain', 'Display name cannot be empty');

    // Verify display name was not updated
    cy.get('[data-testid="display-name"]').should('contain', 'John Doe');

    // Attempt to save with only spaces
    cy.get('[data-testid="name-input"]').clear().type('   ');
    cy.get('[data-testid="save-name-btn"]').click();

    // Verify error message persists
    cy.get('[data-testid="error-toast"]').should('be.visible').should('contain', 'Display name cannot be empty');

    // Verify display name was not updated
    cy.get('[data-testid="display-name"]').should('contain', 'John Doe');

    // Verify edit button is still visible
    cy.get('[data-testid="edit-name-btn"]').should('be.visible');
  });
});
